from collections import deque

def transform(grid):
    H,W=len(grid),len(grid[0])
    # Full line of 2s: determine direction toward it.
    wall=None
    for r in range(H):
        if all(grid[r][c]==2 for c in range(W)):
            wall=('row',r); break
    if wall is None:
        for c in range(W):
            if all(grid[r][c]==2 for r in range(H)):
                wall=('col',c); break
    if wall is None: return [row[:] for row in grid]
    axis,pos=wall
    dr,dc=(1,0) if axis=='row' and pos==0 else (-1,0) if axis=='row' else (0,1) if pos==0 else (0,-1)
    # Components of all nonzero non-wall colors.
    seen=set(); comps=[]
    for r in range(H):
        for c in range(W):
            if grid[r][c] not in (0,2) and (r,c) not in seen:
                color=grid[r][c]; q=[(r,c)]; seen.add((r,c)); comp=[]
                while q:
                    x,y=q.pop(); comp.append((x,y))
                    for nx,ny in ((x+1,y),(x-1,y),(x,y+1),(x,y-1)):
                        if 0<=nx<H and 0<=ny<W and (nx,ny) not in seen and grid[nx][ny]==color:
                            seen.add((nx,ny)); q.append((nx,ny))
                comps.append((color,comp))
    # Closest first in the direction of travel.
    def key(item):
        _,cells=item
        return min(r*dr+c*dc for r,c in cells)
    comps.sort(key=key, reverse=True) # coordinate projection: toward direction = more positive
    out=[[0]*W for _ in range(H)]
    for r in range(H):
        for c in range(W):
            if grid[r][c]==2: out[r][c]=2
    for color,cells in comps:
        poscells=set(cells)
        while True:
            nxt={(r+dr,c+dc) for r,c in poscells}
            if any(not (0<=r<H and 0<=c<W) or out[r][c] not in (0,color) for r,c in nxt):
                break
            # must not allow into cells occupied by same color other component, but out same color possible. safer occupancy all nonzero
            if any(out[r][c]!=0 for r,c in nxt if (r,c) not in poscells):
                break
            poscells=nxt
        for r,c in poscells: out[r][c]=color
    return out
