                        seen.add((nx, ny))
                        stack.append((nx, ny))
            components.append((color, cells))

    def distance_to_wall(component):
        return max(r * dr + c * dc for r, c in component[1])

    components.sort(key=distance_to_wall, reverse=True)
    out = [[2 if grid[r][c] == 2 else 0 for c in range(w)] for r in range(h)]
    for color, cells in components:
        placed = set(cells)
        while True:
            shifted = {(r + dr, c + dc) for r, c in placed}
            if any(not (0 <= r < h and 0 <= c < w) or out[r][c] != 0
                   for r, c in shifted if (r, c) not in placed):
                break
            placed = shifted
        for r, c in placed:
            out[r][c] = color
    return out
